package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
public class RootStatusRecoveryWiringTest {
 private String s(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n)).replace("\r\n","\n");}
 private String part(String s,String a,String b){int i=s.indexOf(a),j=s.indexOf(b,i);assertTrue(a,i>=0);assertTrue(b,j>i);return s.substring(i,j);}
 @Test public void independentScopeNeverAddsTaskTap(){assertNotEquals(RootStatusRecoveryScope.DIRECTORY,RootReturnReadScope.DIRECTORY);assertNotEquals(RootStatusRecoveryScope.DIRECTORY,RootSelectedPendingScope.DIRECTORY);assertEquals(3,RootStatusRecoveryScope.MAX_FRAMES);assertEquals(180000,RootStatusRecoveryScope.SESSION_TTL);assertEquals(90000,RootStatusRecoveryScope.CAPTURE_TTL);}
 @Test public void issuerRequiresNewVisibleIntentAndRejectsOldLiveModes()throws Exception{String v=s("VisibleCaptureAuthority.java");assertTrue(v.contains("issueStatusRecoveryIntent("));assertTrue(v.contains("statusRecoveryApprovalMatches"));assertTrue(v.contains("click.consume(a,a.requestIdentity(),root,e)"));assertTrue(v.contains("Status recovery live issuer only"));assertTrue(v.contains("Nonlive status recovery fixture required"));}
 @Test public void immutableIntentUsesOnlyNewScopeForNewMode()throws Exception{String i=s("RootReturnReadIntent.java");assertTrue(i.contains("final boolean live,currentOnly,statusRecovery"));assertTrue(i.contains("statusRecovery?RootStatusRecoveryScope.current"));assertTrue(i.contains("statusRecovery?RootStatusRecoveryScope.deadline"));assertTrue(i.contains("statusRecovery?RootStatusRecoveryScope.validIndex"));assertTrue(i.contains("a.currentOnly||!a.statusRecovery"));}
 @Test public void initialTemplateUsesTypedProofNotFakeReturn()throws Exception{String c=s("RootReturnReadController.java");assertTrue(c.contains("BingNavigationSnapshot.CurrentTemplateSource direct"));assertTrue(c.contains("direct.fresh(now)&&direct.matches(template)"));assertTrue(c.contains("EXACT_TEMPLATE_ALREADY_READY"));assertTrue(c.contains("templateReturned="));assertTrue(c.contains("boolean returned(){return template!=null&&clean&&back!=null&&back.commandExitZero();}"));}
 @Test public void unknownActionIsStickyAcrossRepeatedExecute()throws Exception{String c=s("RootReturnReadController.java");assertTrue(c.contains("actionUnknown"));assertTrue(c.contains("catch(RuntimeException|Error failure)"));assertTrue(c.contains("if(actionEntered&&back==null)actionUnknown=true"));assertTrue(c.contains("clean=!actionUnknown&&actor.knownClean()&&ports.metadataClean()"));}
 @Test public void activeRuntimeDoesNotConstructTaskRunOrTap()throws Exception{String r=s("CaptureSessionRuntime.java");String start=part(r,"static CaptureSessionRuntime startStatusRecovery(","private void newReturnSourcePermit()");String nav=part(r,"private void returnBeforeReadOnOwner()","static boolean returnReadUnpresented(");for(String n:new String[]{"NativeAutonomousCardRun.confirmed","new NativeRewardCardSession","TapActor"}){assertFalse(n,start.contains(n));assertFalse(n,nav.contains(n));}assertTrue(nav.contains("forStatusRecovery("));assertTrue(nav.contains("readStatusRecovery(shape)"));assertTrue(nav.contains("RootStatusRecoveryScope.burnReturn("));assertTrue(nav.contains("issueStatusRecoveryFrame("));}
 @Test public void readonlyHolderAndHealthyReportRemainSeparateFromBusiness()throws Exception{String r=s("CaptureSessionRuntime.java");assertTrue(r.contains("returnReadIntent.currentCardsOnly()?ReadOnlyTwoStageRun.Capture.moreCurrentCards("));assertTrue(r.contains("qualifiedCurrentReadSummary(readOnlyObservation,healthy,returnReadIntent.currentCardsOnly())"));assertTrue(r.contains("RootStatusRecoveryScope.store("));String q=part(r,"static String qualifiedCurrentReadSummary(","private void closeReturnReadOnOwner()");assertTrue(q.indexOf("if(!healthy)")<q.indexOf("observation.currentCards()"));assertTrue(q.contains("completeFamily=false businessEligible=false"));}
 @Test public void disclosureAndPriorityAreExplicit()throws Exception{String u=s("RootCaptureUi.java"),a=s("DormantCaptureConfirmationActivity.java");assertTrue(u.contains("v36：独立恢复与当前逐卡只读"));assertTrue(u.contains("03:35 至 05:00"));assertTrue(u.contains("TOP缺失/多值不轮询"));assertTrue(a.indexOf("RootCaptureUi.statusRecoveryChoice")<a.indexOf("RootCaptureUi.selectedPendingChoice"));assertTrue(a.contains("returnReadIntent.statusRecovery()?CaptureSessionRuntime.startStatusRecovery"));}
}
